static const d8_pmap_t *const k_maps[D8_NUM + 1] = {
    k_m_bd, k_m_sd, k_m_sw, k_m_sw, k_m_sw, k_m_sw, k_m_cp, k_m_tune_decay,
    k_m_decay_tune, k_m_decay_tune, k_m_tune_decay, k_m_kit,
};

static const uint8_t d8_fx_slots[4] = {D8P_DRIVE, D8P_DIST, D8P_REV, D8P_DLY};

static d8_pmap_t d8_pmap_at(int track, int i)
{
    int head = (track == D8_KIT) ? d8_nspec[track] : (d8_nspec[track] - D8_FX_N);
    if (i < head)
        return k_maps[track][i];
    i -= head;
    if (i >= 4)
        return (d8_pmap_t){K_PAN, 0, 0};
    return (d8_pmap_t){K_POT, d8_fx_slots[i], 0};
}

static const x0x_param_t *d8_tom_mid(int track, int i)
{
    if (i == 0) {
        if (track == D8_LT)
            return &d8_lt_decay[0];
        if (track == D8_MT)
            return &d8_mt_decay[0];
        return &d8_ht_decay[0];
    }
    return &d8_tom_sound;
}

static const x0x_param_t *d8_spec(int track, int i)
{
    if (track == D8_BD) {
        /* Order Level, Tone, Decay, Tune, Attack — Level/Tune from d8_lvl_tune. */
        if (i == 0)
            return &d8_lvl_tune[0];
        if (i == 1)
            return &d8_bd_mid[0];
        if (i == 2)
            return &d8_bd_mid[1];
        if (i == 3)
            return &d8_lvl_tune[1];
        if (i == 4)
            return &d8_bd_mid[2];
        return &d8_fx_tail[i - D8_BD_HEAD];
    }
    if (track == D8_SD) {
        /* Order Level, Tone, Snappy, Tune, Decay — Level/Tune from d8_lvl_tune. */
        if (i == 0)
            return &d8_lvl_tune[0];
        if (i == 1)
            return &d8_sd_mid[0];
        if (i == 2)
            return &d8_sd_mid[1];
        if (i == 3)
            return &d8_lvl_tune[1];
        if (i == 4)
            return &d8_sd_mid[2];
        return &d8_fx_tail[i - D8_SD_HEAD];
    }
    if (track == D8_LT || track == D8_MT || track == D8_HT) {
        if (i < D8_LTUNE_N)
            return &d8_lvl_tune[i];
        if (i < D8_SW_HEAD)
            return d8_tom_mid(track, i - D8_LTUNE_N);
        return &d8_fx_tail[i - D8_SW_HEAD];
    }
    if (track == D8_RS) {
        if (i < D8_LTUNE_N)
            return &d8_lvl_tune[i];
        if (i < D8_SW_HEAD)
            return &d8_rs_mid[i - D8_LTUNE_N];
        return &d8_fx_tail[i - D8_SW_HEAD];
    }
    if (track == D8_CP) {
        if (i < D8_LTUNE_N)
            return &d8_lvl_tune[i];
        if (i < D8_CP_HEAD)
            return &d8_cp_mid[i - D8_LTUNE_N];
        return &d8_fx_tail[i - D8_CP_HEAD];
    }
    if (track == D8_CB) {
        if (i < D8_LTUNE_N)
            return &d8_lvl_tune[i];
        if (i < D8_HAT_HEAD)
            return &d8_cb_mid[i - D8_LTUNE_N];
        return &d8_fx_tail[i - D8_HAT_HEAD];
    }
    if (track == D8_CH) {
        if (i < D8_LTUNE_N)
            return &d8_lvl_tune[i];
        if (i < D8_HAT_HEAD)
            return &d8_ch_mid[i - D8_LTUNE_N];
        return &d8_fx_tail[i - D8_HAT_HEAD];
    }
    if (track == D8_CY) {
        if (i == 0)
            return &d8_lvl_tune[0];
        if (i == 1)
            return &d8_cy_mid[0];
        if (i == 2)
            return &d8_lvl_tune[1];
        return &d8_fx_tail[i - D8_CY_HEAD];
    }
    if (track == D8_OH) {
        if (i == 0)
            return &d8_lvl_tune[0];
        if (i == 1)
            return &d8_oh_mid[0];
        if (i == 2)
            return &d8_lvl_tune[1];
        return &d8_fx_tail[i - D8_CY_HEAD];
    }
    return &k_p_kit[i];
}

/* the sound a track plays, by its switch */
__attribute__((noinline)) static int track_sound(const drum808_t *d, int t)
{
    static const uint8_t k_snd[D8_NUM][2] = {
        {D8S_BD, D8S_BD}, {D8S_SD, D8S_SD}, {D8S_LT, D8S_LC}, {D8S_MT, D8S_MC}, {D8S_HT, D8S_HC},
        {D8S_RS, D8S_CL}, {D8S_CP, D8S_MA}, {D8S_CB, D8S_CB}, {D8S_CY, D8S_CY}, {D8S_OH, D8S_OH},
        {D8S_CH, D8S_CH}};
    return k_snd[t][d->sw[t] & 1];
}

int drum808_nparams(int track) { return track >= 0 && track <= D8_KIT ? d8_nspec[track] : 0; }

/* UI / MIDI pot metadata — not the 808 audio render (X0X_COLD) */
X0X_COLD const x0x_param_t *drum808_param(int track, int i)
{
    if (track < 0 || track > D8_KIT || i < 0 || i >= d8_nspec[track])
        return 0;
    return d8_spec(track, i);
}

__attribute__((noinline)) static void kit_apply(drum808_t *d)
{
    d->vol = (float)d->kpot[0] / 127.0f;
    d->vel_depth = (float)d->kpot[1] / 127.0f;
    d->choke = 1;                                 /* CH cuts OH */
}

/* UI/MIDI pot path — not the 808 audio render (X0X_COLD). drum808_init stays hot/untouched. */
X0X_COLD void drum808_set(drum808_t *d, int track, int i, int value)
{
    d8_pmap_t m;
    const x0x_param_t *p = drum808_param(track, i);
    if (!p)
        return;
    if (value < 0) value = 0;
    if (value > p->max) value = p->max;
    m = d8_pmap_at(track, i);
    switch (m.kind) {
    cas

e K_POT: set_pot(d, track_sound(d, track), m.slot, value); break;
    case K_FIXED: set_pot(d, m.snd, m.slot, value); break;
    case K_SWITCH: d->sw[track] = (uint8_t)value; break;
    case K_PAN:
        d->tpan[track] = (uint8_t)value;
        x0x_pan_gains(value, &d->pan_l[track], &d->pan_r[track]);
        break;
    default: d->kpot[m.slot] = (uint8_t)value; kit_apply(d); break;
    }
}

/* UI / tests only — not the audio render (X0X_COLD) */
X0X_COLD int drum808_get(const drum808_t *d, int track, int i)
{
    d8_pmap_t m;
    if (!drum808_param(track, i))
        return 0;
    m = d8_pmap_at(track, i);
    switch (m.kind) {
    case K_POT: return d->pot[track_sound(d, track)][m.slot];
    case K_FIXED: return d->pot[m.snd][m.slot];
    case K_SWITCH: return d->sw[track];
    case K_PAN: return d->tpan[track];
    default: return d->kpot[m.slot];
    }
}

/* ======================================================================= */
/* the engine                                                              */
/* ======================================================================= */

enum { L_BD, L_SD, L_T0, L_T1, L_T2, L_RS, L_CL, L_MA, L_CP, L_CB, L_CH, L_OH, L_CY, L_NUM };

void drum808_init(drum808_t *d)
{
    int s, k;
    {
        uint8_t *z = (uint8_t *)d;                /* no libc headers on the target */
        unsigned i;
        for (i = 0; i < sizeof *d; i++)
            z[i] = 0;
    }
    for (s = 0; s < D8S_NUM; s++)
        for (k = 0; k < D8P_NUM; k++)
            set_pot(d, s, k, d8_kspec(s, k)->def);
    for (s = 0; s < D8_NUM; s++) {
        d->tpan[s] = 64;                          /* centre */
        d->pan_l[s] = d->pan_r[s] = d->pan_lc[s] = d->pan_rc[s] = 1.0f;
    }
    d->kpot[0] = 100;
    d->kpot[1] = 127;
    kit_apply(d);

    rng_seed(&d->sd.rng, 0x808D51Eu);
    sd_reset(&d->sd);
    bd_reset(&d->bd);
    for (k = 0; k < 3; k++) {                     /* one channel per track, tom-side seed */
        rng_seed(&d->tom[k].rng, 0x808704Du);
        tom_reset(&d->tom[k]);
    }
    rng_seed(&d->rs.rng, 0x8081DDAu);
    sc_peak_set(&d->rs.peak, 464.0f, 0.44f, 1.584893192f);
    rng_seed(&d->cp.rng, 0x808C1A7u);
    bp_set(&d->cp.bp, CP_F, CP_Q);
    sc_hpf_set(&d->cp.hp, 720.0f);
    rng_seed(&d->ma.rng, 0x808AAAC5u);
    ma_tune(&d->ma, 1.0f);

    for (k = 0; k < 6; k++)                       /* SchmittBank::init: phases 0.25 i */
        d->bank.ph[k] = (uint32_t)(k & 3) << 30;
    d->bank.pend_wrap = (1u << 4) | (1u << 5);    /* 1.0 and 1.25 wrap on the first tick */
    rng_seed(&d->bank.rng, 0x808D51F7u);
    bank_ratio(&d->bank, 1.0f);
    cy_init(&d->cy);
    hat_init(&d->ch, 0);
    hat_init(&d->oh, 1);
    cb_init(&d->cb);

    for (k = 0; k < L_NUM; k++) {
        d->lane[k].hit = 1.0f;
        d->lane[k].cg = 1.0f;
    }
    d->lane[L_BD].snd = D8S_BD; d->lane[L_SD].snd = D8S_SD;
    d->lane[L_T0].snd = D8S_LT; d->lane[L_T1].snd = D8S_MT; d->lane[L_T2].snd = D8S_HT;
    d->lane[L_RS].snd = D8S_RS; d->lane[L_CL].snd = D8S_CL; d->lane[L_MA].snd = D8S_MA;
    d->lane[L_CP].snd = D8S_CP; d->lane[L_CB].snd = D8S_CB; d->lane[L_CH].snd = D8S_CH;
    d->lane[L_OH].snd = D8S_OH; d->lane[L_CY].snd = D8S_CY;
}

__attribute__((noinline)) static void choke_lane(d8_lane_t *l)
{
    if (l->cg > 0.0f && l->cstep == 0.0f)
        l->cstep = -1.0f / (0.002f * SR);
}

__attribute__((noinline)) static float lane_hz(int s, float tune) { return d8_midicps(k_base_note[s] + tune); }

void drum808_trigger(drum808_t *d, int track, float vel)
{
    int s, lane;
    float vgain, volts, soft, tune, decay;
    const float *pv;
    const uint8_t *pot;
    if (track < 0 || track >= D8_NUM || !(vel > 0.0f))
        return;                                   /* drums are one-shots: no note-off */
    if (vel > 1.0f)
        vel = 1.0f;
    s = track_sound(d, track);
    pv = d->potv[s];
    pot = d->pot[s];
    tune = pv[D8P_TUNE];
    decay = pv[D8P_DECAY];

    /* 8W8's velocity line: a trigger voltage on the circuit lanes (4 V floor,
     * 7.3 V at full), the rest as gain */
    vgain = SC808_FULL_VELOCITY_GAIN * (1.0f - d->vel_depth * (1.0f - vel));
    volts = 4.0f + 10.0f * ((vgain > 1.0f ? vgain : 1.0f) - 1.0f) / 3.0f;
    if (volts < 4.0f) volts = 4.0f;
    if (volts > 14.0f) volts = 14.0f;
    soft = vgain < 1.0f ? vgain : 1.0f;

    switch (track) {
    case D8_LT: case D8_MT: case D8_HT: lane = L_T0 + (track - D8_LT); break;
    case D8_RS: lane = s == D8S_CL ? L_CL : L_RS; break;
    case D8_CP: lane = s == D8S_MA ? L_MA : L_CP; break;
    case D8_CB: lane = L_CB; break;
    case D8_CY: lane = L_CY; break;
    case D8_OH: lane = L_OH; break;
    case D8_CH: lane = L_CH; break;
    default: lane = track; break;                 /* BD, SD */
    }
    d->lane[lane].hit = vgain;
    d->lane[lane].pk = 0.0f;
    d->lane[lane].qn = 0;
    d->lane[lane].cg = 1.0f;
    d->lane[lane].cstep = 0.0f;
    d->lane[lane].snd = (uint8_t)s;

    /* the hats share one metal source: CH cuts OH (Mutual: OH cuts CH too) */
    if (track == D8_CH && d->choke >= 1) { choke_lane(&d->lane[L_OH]); hat_choke(&d->oh); }
    if (track == D8_OH && d->choke == 2) { choke_lane(&d->lane[L_CH]); hat_choke(&d->ch); }

    switch (s) {
    case D8S_BD:
        bd_trigger(&d->bd, lane_hz(s, tune), (float)pot[D8P_DECAY] / 127.0f, (float)pot[D8P_X1] / 127.0f,
                   (float)pot[D8P_X2] / 127.0f, volts);
        d->lane[lane].hit = soft;
        break;
    case D8S_SD: {
        /* Tone: the 808 panel's (8W8 fixes it at the centre, 0.5 = pot 64) */
        int tp = pot[D8P_X2];
        float tone = tp <= 64 ? (float)tp * (1.0f / 128.0f) : 0.5f + (float)(tp - 64) * (0.5f / 63.0f);
        sd_trigger(&d->sd, d8_exp2_cr(tune / 12.0f), (float)pot[D8P_DECAY] / 127.0f, tone,
                   (float)pot[D8P_X1] / 127.0f, volts);
        d->lane[lane].hit = soft;
        break;
    }
    case D8S_LT: case D8S_MT: case D8S_HT: case D8S_LC: case D8S_MC: case D8S_HC:
        tom_trigger(&d->tom[lane - L_T0], s >= D8S_LC, lane_hz(s, tune), decay, volts);
        d->lane[lane].hit = soft;
        break;
    case D8S_RS:
        rs_trigger(&d->rs, lane_hz(s, tune), decay * 9.12f, d8_midicps(63.0f + tune), d8_midicps(118.0f + tune));
        break;
    case D8S_CL:
        cl_trigger(&d->cl, d8_exp2_cr(tune / 12.0f), (float)pot[D8P_DECAY] / 127.0f, volts);
        d->lane[lane].hit = soft;
        break;
    case D8S_MA:
        ma_trigger(&d->ma, d8_exp2_cr(tune / 12.0f), decay, (float)pot[D8P_X1] / 127.0f, volts);
        d->lane[lane].hit = soft;
        break;
    case D8S_CP:
        cp_trigger(&d->cp, d8_exp2_cr(tune / 12.0f), decay);
        break;
    case D8S_CB:
        bank_ratio(&d->bank, tune);
        cb_ratio(&d->cb, tune);
        cb_trigger(&d->cb, decay, volts);
        d->lane[lane].hit = soft;
        break;
    case D8S_CH:                                  /* hats and cymbal: velocity is a gain */
        bank_ratio(&d->bank, tune);
        hat_trigger(&d->ch, decay, 4.0f);
        break;
    case D8S_OH:
        bank_ratio(&d->bank, tune);
        hat_trigger(&d->oh, decay, 4.0f);
        break;
    default:                                      /* CY */
        bank_ratio(&d->bank, tune);
        cy_ratio(&d->cy, tune);
        cy_trigger(&d->cy, decay, 4.0f);
        break;
    }
}

static int voice_active(const drum808_t *d, int l)
{
    switch (l) {
    case L_BD: return d->bd.active;
    case L_SD: return d->sd.active;
    case L_T0: case L_T1: case L_T2: return d->tom[l - L_T0].active;
    case L_RS: return d->rs.active;
    case L_CL: return d->cl.active;
    case L_MA: return d->ma.active;
    case L_CP: return d->cp.active;
    case L_CB: return d->cb.active;
    case L_CH: return d->ch.active;
    case L_OH: return d->oh.active;
    default: return d->cy.active;
    }
}

/* X0X: a voice's tail ends once it has stayed 60 dB under the hit's own peak for 20 ms. 8W8 runs
 * each voice until its output is under -90 dBFS-ish (3.2e-5, or the metal voices' envelopes), so a
 * voice spends 12..87 % of its life (cymbal .. rim shot; cowbell 51 %) under -60 dB of its peak,
 * at full cost: the 808 was the biggest share of the renders that ran over. D8_TAIL_DB=0 keeps
 * 8W8's endings (the reference test). */
#ifndef D8_TAIL_DB
#define D8_TAIL_DB 1
#endif
#define D8_TAIL_K 1.0e-3f              /* -60 dB */
#define D8_TAIL_N 882                  /* 20 ms: the gaps between a clap's bursts are shorter */
#define D8_TAIL_FLOOR 1.0e-2f          /* the hit has sounded (voices peak at 0.2 .. 7) */
#if D8_TAIL_DB
__attribute__((noinline)) static void voice_stop(drum808_t *d, int l)
{
    switch (l) {
    case L_BD: d->bd.active = 0; break;
    case L_SD: d->sd.active = 0; break;
    case L_T0: case L_T1: case L_T2: d->tom[l - L_T0].active = 0; break;
    case L_RS: d->rs.active = 0; break;
    case L_CL: d->cl.active = 0; break;
    case L_MA: d->ma.active = 0; break;
    case L_CP: d->cp.active = 0; break;
    case L_CB: d->cb.active = 0; break;
    case L_CH: d->ch.active = 0; break;
    case L_OH: d->oh.active = 0; break;
    default: d->cy.active = 0; break;
    }
}
__attribute__((noinline)) static void lane_tail(drum808_t *d, int l, const float *buf, int m)
{
    d8_lane_t *ln = &d->lane[l];
    float pk = ln->pk;
    int32_t qn = ln->qn;
    int i;
    for (i = 0; i < m; i++) {
        float a = buf[i] < 0.0f ? -buf[i] : buf[i];
        if (a > pk)
            pk = a;
        if (a > pk * D8_TAIL_K)
            qn = 0;
        else
            qn++;
    }
    ln->pk = pk;
    ln->qn = qn;
    if (qn > D8_TAIL_N && pk > D8_TAIL_FLOOR)       /* (a metal voice opens late: it has to have sounded) */
        voice_stop(d, l);
}
#endif

__attribute__((noinline)) static int lane_on(const drum808_t *d, int l) { return d->lane[l].cg > 0.0f && voice_active(d, l); }

int drum808_active(const drum808_t *d)
{
    int l;
    for (l = 0; l < L_NUM; l++)
        if (lane_on(d, l))
            return 1;
    return 0;
}

/* Run one voice for up to m samples into buf; stops where 8W8 would stop calling
 * it (the voice went inactive). Returns the samples written. */
static __attribute__((noinline)) int voice_run(drum808_t *d, int l, float *buf, int m, const float *bus, const float *pair)
{
    int i;
    switch (l) {
    case L_BD: for (i = 0; i < m && d->bd.active; i++) buf[i] = bd_tick(&d->bd); break;
    case L_SD: for (i = 0; i < m && d->sd.active; i++) buf[i] = sd_tick(&d->sd); break;
    case L_T0: case L_T1: case L_T2: {
        d8_tom_t *t = &d->tom[l - L_T0];
        for (i = 0; i < m && t->active; i++) buf[i] = tom_tick(t);
        break;
    }
    case L_RS: for (i = 0; i < m && d->rs.active; i++) buf[i] = rs_tick(&d->rs); break;
    case L_CL: for (i = 0; i < m && d->cl.active; i++) buf[i] = cl_tick(&d->cl); break;
    case L_MA: for (i = 0; i < m && d->ma.active; i++) buf[i] = ma_tick(&d->ma); break;
    case L_CP: for (i = 0; i < m && d->cp.active; i++) buf[i] = cp_tick(&d->cp); break;
    case L_CB: for (i = 0; i < m && d->cb.active; i++) buf[i] = cb_tick(&d->cb, pair[i]); break;
    case L_CH: for (i = 0; i < m && d->ch.active; i++) buf[i] = hat_tick(&d->ch, bus[i]); break;
    case L_OH: for (i = 0; i < m && d->oh.active; i++) buf[i] = hat_tick(&d->oh, bus[i]); break;
    default: for (i = 0; i < m && d->cy.active; i++) buf[i] = cy_tick(&d->cy, bus[i]); break;
    }
    return i;
}

/* trim, drive, level x velocity x choke, into the three buses (sends post-fader) */
/* the track each lane belongs to (its pan): the clave is the RS track's, the maracas the CP's */
static const uint8_t k_lane_track[L_NUM] = {D8_BD, D8_SD, D8_LT, D8_MT, D8_HT, D8_RS, D8_RS, D8_CP, D8_CP,
                                            D8_CB, D8_CH, D8_OH, D8_CY};
static float *d8_dry_r;         /* the render in progress: its right side (0: mono) */

__attribute__((noinline)) static void lane_mix(drum808_t *d, d8_lane_t *l, const float *buf, int m, float *dry, float *rev, float *dly,
                     uint16_t audible_tracks)
{
    const int tr = k_lane_track[l - d->lane];
    float *dry_r = d8_dry_r;
    const float pl = d->pan_lc[tr], pr = d->pan_rc[tr], dpl = d->pan_dl[tr], dpr = d->pan_dr[tr];
    int s = l->snd, i, type = d->pot[s][D8P_DIST];
    const d8_shp_t *p = &d->shp[s];
    float trim = k_trim[s], g = d->potv[s][D8P_LEVEL] * l->hit * d->vol;
    float ra = d->potv[s][D8P_REV], da = d->potv[s][D8P_DLY];
    int bypass = p->drive < 1.0e-3f;
    if (!(audible_tracks & (1u << tr))) g = 0.0f; /* retain envelope, choke and crush state while inaudible */
    if (l->cstep == 0.0f && bypass) {             /* the common case */
        float k = trim * g * l->cg;
        if (dry_r) {
            for (i = 0; i < m; i++) {
                dry[i] += buf[i] * (k * (pl + dpl * (float)i));
                dry_r[i] += buf[i] * (k * (pr + dpr * (float)i));
            }
        } else
            for (i = 0; i < m; i++)
                dry[i] += buf[i] * k;
        if (ra > 0.0f)
            for (i = 0; i < m; i++) rev[i] += buf[i] * k * ra;
        if (da > 0.0f)
            for (i = 0; i < m; i++) dly[i] += buf[i] * k * da;
        return;
    }
    for (i = 0; i < m; i++) {
        float x, sv;
        if (l->cstep < 0.0f) {
            l->cg += l->cstep;
            if (l->cg <= 0.0f) {
                l->cg = 0.0f;
                l->cstep = 0.0f;
            }
        }
        if (l->cg <= 0.0f)
            break;
        x = buf[i] * trim;
        if (!bypass)
            x = shape(x, p, type, l->crush);
        sv = x * g * l->cg;
        if (dry_r) {
            dry[i] += sv * (pl + dpl * (float)i);
            dry_r[i] += sv * (pr + dpr * (float)i);
        } else
            dry[i] += sv;
        rev[i] += sv * ra;
        dly[i] += sv * da;
    }
}

static void d8_render(drum808_t *d, float *dry, float *rev, float *dly, int n, uint16_t audible_tracks)
{
    float buf[CHUNK], bus[CHUNK], pair[CHUNK];
    int off, l, i;
    for (off = 0; off < n; off += CHUNK) {
        int m = n - off < CHUNK ? n - off : CHUNK;
        int cb_on = lane_on(d, L_CB);
        if (d8_dry_r)                                 /* the tracks' pans glide over this chunk */
            for (l = 0; l < D8_NUM; l++) {
                d->pan_dl[l] = x0x_glide_block(&d->pan_lc[l], d->pan_l[l], m);
                d->pan_dr[l] = x0x_glide_block(&d->pan_rc[l], d->pan_r[l], m);
            }
        /* the shared bank runs only while a metal voice sounds */
        if (cb_on || lane_on(d, L_CH) || lane_on(d, L_OH) || lane_on(d, L_CY)) {
            d8_bank_t *b = &d->bank;
            for (i = 0; i < m; i++) {
                bus[i] = bank_tick(b);
                if (cb_on)
                    pair[i] = ((b->ph[4] < BANK_DUTY ? 2.5f : -2.5f) + (b->ph[5] < BANK_DUTY ? 2.5f : -2.5f)) * 0.5f;
            }
        }
        for (l = 0; l < L_NUM; l++) {
            d8_lane_t *ln = &d->lane[l];
            int mm = m, got;
            if (!lane_on(d, l))
                continue;
            if (ln->cstep < 0.0f) {               /* 8W8 stops calling a voice whose choke ran out */
                float c = ln->cg;
                for (i = 0; i < m; i++) {
                    c += ln->cstep;
                    if (c <= 0.0f) {
                        mm = i + 1;
                        break;
                    }
                }
            }
            got = voice_run(d, l, buf, mm, bus, pair);
            {
                float *dr = d8_dry_r;                     /* the chunk's slice of the right side */
                d8_dry_r = dr ? dr + off : 0;
                lane_mix(d, ln, buf, got, dry + off, rev + off, dly + off, audible_tracks);
                d8_dry_r = dr;
            }
#if D8_TAIL_DB
            lane_tail(d, l, buf, got);
#endif
        }
    }
}

void drum808_render(drum808_t *d, float *dry, float *rev, float *dly, int n)
{
    d8_dry_r = 0;
    d8_render(d, dry, rev, dly, n, 0x7FFu);
}

void drum808_pan_settle(drum808_t *d)
{
    int t;
    for (t = 0; t < D8_NUM; t++) {
        d->pan_lc[t] = d->pan_l[t];
        d->pan_rc[t] = d->pan_r[t];
    }
}

void drum808_render_st_masked(drum808_t *d, float *dry_l, float *dry_r, float *rev, float *dly,
                             int n, uint16_t audible_tracks)
{
    d8_dry_r = dry_r;
    d8_render(d, dry_l, rev, dly, n, audible_tracks);
    d8_dry_r = 0;
}

void drum808_render_st(drum808_t *d, float *dry_l, float *dry_r, float *rev, float *dly, int n)
{
    drum808_render_st_masked(d, dry_l, dry_r, rev, dly, n, 0x7FFu);
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X platform on the FM-1: plat.h over Felucca's HAL, panel map, USB rings and storage.
 * Part of the unity build (x0x.c), after the HAL, usb.c, storage.c and panel.c. */

/* Full target store ordering for the BREAK pulse publication. */
#include "../../hal/fm1_sync.h"

/* Main-loop CQ producer and ALNK0 consumer share CPU0. Source masking leaves
 * MIDI/clock IRQs alone and never changes the caller's global IRQ state. */
uint32_t plat_cq_lock(void)
{
    return fm1_irq_mask_save(FM1_IRQ_ALNK0);
}
void plat_cq_unlock(uint32_t state)
{
    fm1_irq_mask_restore(FM1_IRQ_ALNK0, state);
}

uint32_t plat_ms(void) { return fm1_ms; }

uint32_t plat_buttons(void)
{
    uint32_t raw = fm1_in.buttons, out = 0, i;
#if BOARD_SMK37
    extern uint8_t smk_clip_mode_on(void);
    uint8_t clip_mode = smk_clip_mode_on();
#if X0X_DEV_PADCAL
    extern uint8_t smk_padcal_on(void);
    if (smk_padcal_on())
        return 0u;   /* the pad calibration has the buttons (main_fm1.c, CLP-79) */
#endif
#endif
    for (i = 0; i < NB; i++)
        if (raw & (1u << panel.btn[i])) {
#if BOARD_SMK37
            /* APC navigation controls must not also trigger X0X page/octave actions. */
            if (clip_mode && panel.btn[i] <= FM1_BTN_OCT_UP)
                continue;
            /* Clip mode: SCALE, CHORD, ARP and NOTE REPEAT belong to the clip keys (main_fm1.c). */
            if (clip_mode && (i == B_SEL || i == B_ENV || i == B_ARP || i == B_LFO))
                continue;
#endif
            out |= 1u << i;
        }
    return out;
}

uint32_t plat_keys(void) { return fm1_in.notes & ((1u << NKEYS) - 1u); }

int plat_division_pad(unsigned owner)
{
#if BOARD_SMK37
    uint32_t flags = irq_save();
    int hit = smk__division_poll(owner);
    irq_restore(flags);
    return hit;
#else
    (void)owner;
    return -1;
#endif
}

uint8_t plat_key_velocity(int key)
{
#if BOARD_SMK37
    if ((unsigned)key < NKEYS) {
        uint8_t v = fm1_in.key_vel[SMK_KEY_F3 + key];
        if (v)
            return v;
    }
#else
    (void)key;
#endif
    return 100;
}

int32_t plat_enc(int role)
{
    if (role < 0 || role >= NE)
        return 0;
#if BOARD_SMK37
    extern uint8_t smk_ck_knobs_owned(void);
#if X0X_DEV_PADCAL
    extern uint8_t smk_padcal_on(void);
    if (smk_ck_knobs_owned() || smk_padcal_on())
#else
    if (smk_ck_knobs_owned())
#endif
        return 0;   /* clip mode: knobs 2-8 send CCs (main_fm1.c ck_controls); knob 1 stays MASTER. Pad calibration: K2-K4 */
#endif
    return fm1_enc_take(panel.enc[role]) * panel.dir[role];
}

static volatile uint32_t master_q12 = 2048;
uint32_t plat_master(void) { return master_q12; }

/* the battery: ADC ch3 (its divider), smoothed by the main loop. The stock firmware's thresholds, as
 * melodee and dxsloop use them, give 0-3 bars; there is no charger line, so a USB host means power */
static int32_t batt_raw;
int plat_battery(void)
{
    if (usb.config && !usb.suspended)
        return 4;
    if (!batt_raw)
        return -1;
    return batt_raw >= 591 ? 3 : batt_raw >= 561 ? 2 : batt_raw >= 531 ? 1 : 0;
}

#if BOARD_SMK37
/* SMK-37 Pro LEDs (smk_input.h, lcd.c): the button LEDs are on / off (no dim layer: no glow); the 16 RGB pads
 * show the 16 white keys (the steps; HOME: the patterns), lit bright and dim dim in the colour of the part on
 * screen (app/main_fm1.c smk_pads, after the frame). The keybed has no LEDs: what the FM-1 shows on its black
 * keys (tracks, slices, part mutes) is on the screen only. */
static uint8_t smk_fbank;                           /* FADER BANK: 0 = A, 1 = B (main_fm1.c smk_faders); its LED */
static uint32_t smk_keys_lit, smk_keys_dim;         /* the key picture of the last frame, for the pads */
static void led_pos_init(void) {}
void plat_glow(int on) { (void)on; }
void plat_play_red(int red) { (void)red; }           /* (SEQ PLAY has one LED) */
void plat_keys_dim(uint32_t keys) { smk_keys_dim = keys; }
void plat_leds(uint32_t buttons, uint32_t keys)
{
    uint8_t nl[SMK_NLED] = {0};
    uint32_t i;
    for (i = 0; i < NB; i++)
        if ((buttons >> i) & 1u)
            nl[panel.btn[i]] = 1;
    nl[SMK_BTN_FADER_BANK] = smk_fbank != 0;
    for (i = 0; i < SMK_NLED; i++)
        fm1_led[i] = nl[i];
    smk_keys_lit = keys;
}
#else
/* LEDs: the picture is built off-line and copied one byte per column (Felucca: clearing
 * and relighting would let the 10 kHz scan catch the dark gap and flicker).
 * led_pos[id] = (col << 3) | row from FM1_KEYMAP (was rebuilt into BSS at boot). */
static const uint8_t led_pos[FM1_NKEY] = {
    4, 12, 49, 33, 17, 1, 74, 66, 57, 41, 25, 9, 82, 58, 28, 20, 44, 36, 60, 52, 68, 76, 84,
    3, 11, 19, 27, 35, 43, 51, 59, 67, 75, 83, 2, 10, 18, 26, 34, 50, 42};
static void led_pos_init(void) {}
/* Glow: every button not lit is lit dim, on one scan frame in GLOW_DIV (the HAL's fm1_led_dim) */
#define GLOW_DIV 4u
static uint8_t glow_on = 1;
void plat_glow(int on) { glow_on = (uint8_t)(on != 0); }
/* PLAY has two LEDs: its red at the button's own position, a green at the keyless matrix position
 * column 8, row PA5 (found on the device). Green, unless recording. */
static uint8_t play_red;
void plat_play_red(int red) { play_red = (uint8_t)(red != 0); }
static uint32_t keys_dim;
void plat_keys_dim(uint32_t keys) { keys_dim = keys; }
void plat_leds(uint32_t buttons, uint32_t keys)
{
    uint8_t nl[FM1_NCOL] = {0}, dl[FM1_NCOL] = {0};
    uint32_t i, c;
    for (i = 0; i < NB + NKEYS; i++) {
        uint32_t id = i < NB ? panel.btn[i] : 14u + (i - NB);
        int on = i < NB ? (buttons >> i) & 1u : (keys >> (i - NB)) & 1u;
        uint8_t q = led_pos[id];
        if (i == B_PLAY && !play_red)            /* PLAY's green LED instead (keyless position col 8, row PA5) */
            q = (uint8_t)((8u << 3) | 1u);
        if (q == 0xFF)
            continue;
        if (on)
            nl[q >> 3] |= (uint8_t)(1u << (q & 7u));
        else if (i < NB ? glow_on : (keys_dim >> (i - NB)) & 1u)
            dl[q >> 3] |= (uint8_t)(1u << (q & 7u));
    }
    for (c = 0; c < FM1_NCOL; c++) {
        fm1_led[c] = nl[c];
        fm1_led_dim[c] = dl[c];
    }
    fm1_led_dim_div = glow_on || keys_dim ? GLOW_DIV : 0u;
}
